import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 2011;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        while (true) {
            int h = Integer.parseInt(br.readLine());
            if (h == 0) break;
            char[][] grid = new char[h][];
            for (int i = 0; i < h; i++) {
                grid[i] = br.readLine().toCharArray();
            }
            int[] pos = new int[2]; // row, col
            // find top-leftmost non-space character
            outer:
            for (int r = 0; r < h; r++) {
                for (int c = 0; c < grid[r].length; c++) {
                    if (grid[r][c] != ' ') {
                        pos[0] = r;
                        pos[1] = c;
                        break outer;
                    }
                }
            }
            int result = evaluate(grid, pos);
            sb.append(result).append("\n");
        }
        System.out.print(sb);
    }

    static int evaluate(char[][] grid, int[] pos) {
        int r = pos[0], c = pos[1];
        char ch = grid[r][c];

        if (ch >= '0' && ch <= '9') {
            // number
            int val = 0;
            while (c < grid[r].length && grid[r][c] >= '0' && grid[r][c] <= '9') {
                val = (val * 10 + (grid[r][c] - '0')) % MOD;
                c++;
            }
            pos[1] = c;
            return val;
        }

        if (ch == '+' || ch == '-' || ch == '*') {
            pos[1]++; // skip operator
            int left = evaluate(grid, pos);
            int right = evaluate(grid, pos);
            if (ch == '+') return (left + right) % MOD;
            if (ch == '-') return (left - right + MOD) % MOD;
            return (left * right) % MOD;
        }

        if (ch == '/') {
            // fraction: numerator above, denominator below
            // find the width of the fraction bar
            int barR = r;
            int barC = c;
            int width = 0;
            while (barC < grid[barR].length && grid[barR][barC] == '-') {
                width++;
                barC++;
            }
            // numerator is directly above the bar, centered
            int numStartCol = c;
            int numEndCol = c + width - 1;
            // find actual numerator start (non-space) inside that range
            int numR = barR - 1;
            int numC = numStartCol;
            while (numC <= numEndCol && (numC >= grid[numR].length || grid[numR][numC] == ' ')) numC++;
            if (numC > numEndCol) {
                // no numerator? treat as 0
                pos[0] = barR + 1;
                pos[1] = numStartCol;
                int denom = evaluate(grid, pos);
                return (0 * modInverse(denom, MOD)) % MOD;
            }
            int[] numPos = new int[]{numR, numC};
            int numerator = evaluate(grid, numPos);
            // denominator is directly below the bar
            int denR = barR + 1;
            int denC = numStartCol;
            while (denC <= numEndCol && (denC >= grid[denR].length || grid[denR][denC] == ' ')) denC++;
            if (denC > numEndCol) {
                // no denominator? treat as 1? but problem guarantees valid
                pos[0] = denR;
                pos[1] = numStartCol;
                return numerator % MOD;
            }
            int[] denPos = new int[]{denR, denC};
            int denominator = evaluate(grid, denPos);
            pos[0] = denPos[0];
            pos[1] = denPos[1];
            return (numerator * modInverse(denominator, MOD)) % MOD;
        }

        if (ch == '^') {
            // exponent: base below, exponent above
            int hatR = r, hatC = c;
            // exponent is above
            int expR = hatR - 1;
            int expC = hatC;
            while (expC >= 0 && expC < grid[expR].length && grid[expR][expC] == ' ') expC--;
            if (expC < 0 || expC >= grid[expR].length) expC = hatC;
            int[] expPos = new int[]{expR, expC};
            int exponent = evaluate(grid, expPos);
            // base is below
            int baseR = hatR + 1;
            int baseC = hatC;
            while (baseC >= 0 && baseC < grid[baseR].length && grid[baseR][baseC] == ' ') baseC++;
            if (baseC < 0 || baseC >= grid[baseR].length) baseC = hatC;
            int[] basePos = new int[]{baseR, baseC};
            int base = evaluate(grid, basePos);
            pos[0] = basePos[0];
            pos[1] = basePos[1];
            return modPow(base, exponent, MOD);
        }

        // fallback, shouldn't happen
        pos[1]++;
        return 0;
    }

    static int modPow(int a, int e, int mod) {
        int res = 1;
        a %= mod;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * a) % mod;
            a = (a * a) % mod;
            e >>= 1;
        }
        return res;
    }

    static int modInverse(int a, int mod) {
        // mod is prime 2011
        return modPow(a, mod - 2, mod);
    }
}

import java.io.*;
import java.util.*;

/*
 * ASCII Expression evaluator modulo 2011
 *
 * The exact statement text in the prompt is truncated, but this is the classic
 * "typewriter-style multi-line ASCII math expression" parser/evaluator.
 *
 * Supported constructs:
 * - integers
 * - binary +, -, *
 * - fractions drawn with a horizontal bar
 * - exponents written above-right of a base
 * - parentheses
 *
 * Expressions are given as several rows of equal width (or padded as needed).
 * Multiple datasets are read until EOF.
 *
 * Parsing strategy:
 * We recursively parse a rectangular region [top..bottom] x [left..right].
 *
 * Precedence from low to high:
 *   1) top-level + and -
 *   2) top-level *
 *   3) fraction bar spanning the region
 *   4) exponent attachment
 *   5) atom: parenthesized expr or integer
 *
 * For ASCII layout:
 * - A fraction in a region is recognized by a row made entirely of '-' across
 *   the full trimmed width of the region. The numerator is above that row and
 *   denominator below.
 * - Exponent is recognized for an atom by checking content in the upper-right
 *   area adjacent to the atom's bounding box.
 *
 * Modulo arithmetic uses MOD = 2011, division by modular inverse.
 */
public class Main {
    static final int MOD = 2011;

    static class FastReader {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String nextLine() throws IOException { return br.readLine(); }
    }

    static char[][] g;
    static int H, W;

    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader();
        String line;
        List<String> all = new ArrayList<>();
        while ((line = fr.nextLine()) != null) all.add(line);

        // Common dataset format for these problems:
        // an integer h followed by h lines, repeated until EOF.
        // Since prompt is truncated, we robustly support this format.
        int idx = 0;
        StringBuilder out = new StringBuilder();
        while (idx < all.size()) {
            while (idx < all.size() && all.get(idx).trim().isEmpty()) idx++;
            if (idx >= all.size()) break;

            String s = all.get(idx).trim();
            if (!isInteger(s)) break;
            int h = Integer.parseInt(s);
            idx++;
            List<String> rows = new ArrayList<>();
            for (int i = 0; i < h && idx < all.size(); i++, idx++) rows.add(all.get(idx));

            prepare(rows);
            int ans = evalRegion(0, H - 1, 0, W - 1);
            ans %= MOD;
            if (ans < 0) ans += MOD;
            out.append(ans).append('\n');
        }
        System.out.print(out.toString());
    }

    static boolean isInteger(String s) {
        if (s.isEmpty()) return false;
        int i = 0;
        if (s.charAt(0) == '-') {
            if (s.length() == 1) return false;
            i = 1;
        }
        for (; i < s.length(); i++) if (!Character.isDigit(s.charAt(i))) return false;
        return true;
    }

    static void prepare(List<String> rows) {
        H = rows.size();
        W = 0;
        for (String s : rows) W = Math.max(W, s.length());
        g = new char[H][W];
        for (int i = 0; i < H; i++) {
            String s = rows.get(i);
            for (int j = 0; j < W; j++) g[i][j] = (j < s.length() ? s.charAt(j) : ' ');
        }
    }

    static int evalRegion(int top, int bottom, int left, int right) {
        int[] t = trim(top, bottom, left, right);
        top = t[0]; bottom = t[1]; left = t[2]; right = t[3];
        if (top > bottom || left > right) return 0;

        // Strip enclosing parentheses if they wrap the whole region.
        while (isWrappedByParentheses(top, bottom, left, right)) {
            left++;
            right--;
            t = trim(top, bottom, left, right);
            top = t[0]; bottom = t[1]; left = t[2]; right = t[3];
            if (top > bottom || left > right) return 0;
        }

        // 1) top-level +/-
        int split = findTopLevelAddSub(top, bottom, left, right);
        if (split != -1) {
            char op = g[baseline(top, bottom)][split];
            int lv = evalRegion(top, bottom, left, split - 1);
            int rv = evalRegion(top, bottom, split + 1, right);
            return op == '+' ? add(lv, rv) : sub(lv, rv);
        }

        // 2) top-level *
        split = findTopLevelMul(top, bottom, left, right);
        if (split != -1) {
            int lv = evalRegion(top, bottom, left, split - 1);
            int rv = evalRegion(top, bottom, split + 1, right);
            return mul(lv, rv);
        }

        // 3) fraction
        int fracRow = findFractionRow(top, bottom, left, right);
        if (fracRow != -1) {
            int num = evalRegion(top, fracRow - 1, left, right);
            int den = evalRegion(fracRow + 1, bottom, left, right);
            return mul(num, modPow(den, MOD - 2));
        }

        // 4) exponent
        int[] atom = parseAtomBounds(top, bottom, left, right);
        if (atom != null) {
            int aTop = atom[0], aBottom = atom[1], aLeft = atom[2], aRight = atom[3];
            if (!(aTop == top && aBottom == bottom && aLeft == left && aRight == right)) {
                int base = evalRegion(aTop, aBottom, aLeft, aRight);
                int exp = evalRegion(top, aTop - 1, aRight + 1, right);
                return modPow(base, exp);
            }
        }

        // 5) atom
        return evalAtom(top, bottom, left, right);
    }

    static int evalAtom(int top, int bottom, int left, int right) {
        int[] t = trim(top, bottom, left, right);
        top = t[0]; bottom = t[1]; left = t[2]; right = t[3];
        if (top > bottom || left > right) return 0;

        if (isWrappedByParentheses(top, bottom, left, right)) {
            return evalRegion(top, bottom, left + 1, right - 1);
        }

        // integer
        StringBuilder sb = new StringBuilder();
        int row = baseline(top, bottom);
        boolean ok = true;
        for (int i = top; i <= bottom; i++) {
            if (i == row) continue;
            for (int j = left; j <= right; j++) {
                if (g[i][j] != ' ') ok = false;
            }
        }
        if (ok) {
            for (int j = left; j <= right; j++) if (g[row][j] != ' ') sb.append(g[row][j]);
            String s = sb.toString().trim();
            if (isInteger(s)) {
                long v = Long.parseLong(s);
                v %= MOD;
                if (v < 0) v += MOD;
                return (int) v;
            }
        }

        // Fallback: if region itself is non-empty but unrecognized, try concatenated baseline parse.
        sb.setLength(0);
        for (int j = left; j <= right; j++) if (g[row][j] != ' ') sb.append(g[row][j]);
        String s = sb.toString().trim();
        if (isInteger(s)) {
            long v = Long.parseLong(s);
            v %= MOD;
            if (v < 0) v += MOD;
            return (int) v;
        }

        return 0;
    }

    static int[] parseAtomBounds(int top, int bottom, int left, int right) {
        int row = baseline(top, bottom);
        int l = left;
        while (l <= right && g[row][l] == ' ') l++;
        if (l > right) return new int[]{top, bottom, left, right};

        if (g[row][l] == '(') {
            int depth = 0;
            int r = -1;
            for (int j = l; j <= right; j++) {
                if (g[row][j] == '(') depth++;
                else if (g[row][j] == ')') {
                    depth--;
                    if (depth == 0) {
                        r = j;
                        break;
                    }
                }
            }
            if (r != -1) {
                int aTop = top, aBottom = bottom;
                // shrink vertically to content using [l..r]
                int[] t = trim(top, bottom, l, r);
                return new int[]{t[0], t[1], t[2], t[3]};
            }
        }

        // number on baseline
        int r = l;
        if (g[row][r] == '-') r++;
        boolean hasDigit = false;
        while (r <= right && Character.isDigit(g[row][r])) {
            hasDigit = true;
            r++;
        }
        if (hasDigit) {
            int rr = r - 1;
            int[] t = trim(top, bottom, l, rr);
            return new int[]{t[0], t[1], t[2], t[3]};
        }

        return null;
    }

    static int findTopLevelAddSub(int top, int bottom, int left, int right) {
        int row = baseline(top, bottom);
        int depth = 0;
        for (int j = right; j >= left; j--) {
            char c = g[row][j];
            if (c == ')') depth++;
            else if (c == '(') depth--;
            else if (depth == 0 && (c == '+' || c == '-')) {
                if (isUnaryMinus(row, j, left)) continue;
                if (columnHasOnlyOnBaseline(j, top, bottom, row)) return j;
            }
        }
        return -1;
    }

    static int findTopLevelMul(int top, int bottom, int left, int right) {
        int row = baseline(top, bottom);
        int depth = 0;
        for (int j = right; j >= left; j--) {
            char c = g[row][j];
            if (c == ')') depth++;
            else if (c == '(') depth--;
            else if (depth == 0 && c == '*') {
                if (columnHasOnlyOnBaseline(j, top, bottom, row)) return j;
            }
        }
        return -1;
    }

    static boolean isUnaryMinus(int row, int j, int left) {
        int k = j - 1;
        while (k >= left && g[row][k] == ' ') k--;
        if (k < left) return true;
        char p = g[row][k];
        return p == '+' || p == '-' || p == '*' || p == '(';
    }

    static boolean columnHasOnlyOnBaseline(int col, int top, int bottom, int base) {
        for (int i = top; i <= bottom; i++) {
            if (i == base) continue;
            if (g[i][col] != ' ') return false;
        }
        return true;
    }

    static int findFractionRow(int top, int bottom, int left, int right) {
        for (int i = top; i <= bottom; i++) {
            boolean allDash = true;
            boolean anyDash = false;
            for (int j = left; j <= right; j++) {
                if (g[i][j] == '-') anyDash = true;
                else if (g[i][j] != ' ') {
                    allDash = false;
                    break;
                }
            }
            if (!anyDash) continue;
            // require trimmed row to be all dashes across full trimmed width
            int l = left, r = right;
            while (l <= r && colEmptyInRow(i, l)) l++;
            while (l <= r && colEmptyInRow(i, r)) r--;
            if (l > r) continue;
            boolean ok = true;
            for (int j = l; j <= r; j++) if (g[i][j] != '-') ok = false;
            if (ok && l == left && r == right) return i;
        }
        return -1;
    }

    static boolean colEmptyInRow(int row, int col) {
        return g[row][col] == ' ';
    }

    static boolean isWrappedByParentheses(int top, int bottom, int left, int right) {
        int row = baseline(top, bottom);
        if (g[row][left] != '(' || g[row][right] != ')') return false;
        int depth = 0;
        for (int j = left; j <= right; j++) {
            char c = g[row][j];
            if (c == '(') depth++;
            else if (c == ')') depth--;
            if (depth == 0 && j < right) return false;
        }
        return true;
    }

    static int baseline(int top, int bottom) {
        // choose the row with the most non-space characters as baseline
        int best = top, bestCnt = -1;
        for (int i = top; i <= bottom; i++) {
            int cnt = 0;
            for (int j = 0; j < W; j++) if (g[i][j] != ' ') cnt++;
            if (cnt > bestCnt) {
                bestCnt = cnt;
                best = i;
            }
        }
        return best;
    }

    static int[] trim(int top, int bottom, int left, int right) {
        while (top <= bottom && rowEmpty(top, left, right)) top++;
        while (top <= bottom && rowEmpty(bottom, left, right)) bottom--;
        while (left <= right && colEmpty(left, top, bottom)) left++;
        while (left <= right && colEmpty(right, top, bottom)) right--;
        return new int[]{top, bottom, left, right};
    }

    static boolean rowEmpty(int r, int left, int right) {
        for (int j = left; j <= right; j++) if (g[r][j] != ' ') return false;
        return true;
    }

    static boolean colEmpty(int c, int top, int bottom) {
        for (int i = top; i <= bottom; i++) if (g[i][c] != ' ') return false;
        return true;
    }

    static int add(int a, int b) {
        int x = a + b;
        if (x >= MOD) x -= MOD;
        return x;
    }

    static int sub(int a, int b) {
        int x = a - b;
        if (x < 0) x += MOD;
        return x;
    }

    static int mul(int a, int b) {
        return (int) ((long) a * b % MOD);
    }

    static int modPow(int a, int e) {
        long base = a % MOD;
        if (base < 0) base += MOD;
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            e >>= 1;
        }
        return (int) res;
    }
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

#define MOD 2011
#define MAXN 100
#define MAXL 200

char expr[MAXN][MAXL];
int h, w;

// get number from a single line segment
long long getnum(int r, int c, int len) {
    long long res = 0;
    for (int i = 0; i < len; i++) {
        if (!isdigit(expr[r][c+i])) return -1;
        res = res * 10 + (expr[r][c+i] - '0');
    }
    return res % MOD;
}

// check if region is a number
int isnum(int r, int c, int wdt) {
    for (int i = 0; i < wdt; i++)
        if (!isdigit(expr[r][c+i])) return 0;
    return 1;
}

// find matching closing parenthesis
int match_paren(int r, int c) {
    int depth = 1;
    for (int j = c+1; j < w; j++) {
        if (expr[r][j] == '(') depth++;
        else if (expr[r][j] == ')') {
            depth--;
            if (depth == 0) return j;
        }
    }
    return -1;
}

// evaluate region from (r1,c1) to (r2,c2)
long long eval(int r1, int c1, int r2, int c2);

// evaluate a simple expression inside a single line
long long evalline(int r, int c1, int c2) {
    // remove leading/trailing spaces
    while (c1 <= c2 && expr[r][c1] == ' ') c1++;
    while (c2 >= c1 && expr[r][c2] == ' ') c2--;
    if (c1 > c2) return 0;

    // check for parentheses
    if (expr[r][c1] == '(' && expr[r][c2] == ')') {
        int m = match_paren(r, c1);
        if (m == c2) {
            return eval(r, c1+1, r, c2-1);
        }
    }

    // find lowest precedence operator outside parentheses
    int paren = 0;
    int op_pos = -1;
    char op = 0;
    for (int i = c1; i <= c2; i++) {
        if (expr[r][i] == '(') paren++;
        else if (expr[r][i] == ')') paren--;
        else if (paren == 0) {
            if (expr[r][i] == '+' || expr[r][i] == '-') {
                op_pos = i;
                op = expr[r][i];
            } else if ((expr[r][i] == '*' || expr[r][i] == '/') && op != '+' && op != '-') {
                op_pos = i;
                op = expr[r][i];
            }
        }
    }

    if (op_pos != -1) {
        long long left = evalline(r, c1, op_pos-1);
        long long right = evalline(r, op_pos+1, c2);
        if (op == '+') return (left + right) % MOD;
        if (op == '-') return (left - right + MOD) % MOD;
        if (op == '*') return (left * right) % MOD;
        if (op == '/') {
            if (right == 0) return 0;
            return left / right % MOD;
        }
    }

    // try number
    long long num = getnum(r, c1, c2-c1+1);
    if (num >= 0) return num;

    // fraction or exponent
    // look for horizontal line
    for (int rr = r1; rr <= r2; rr++) {
        int hasdash = 0;
        for (int cc = c1; cc <= c2; cc++) {
            if (expr[rr][cc] == '-') hasdash = 1;
        }
        if (hasdash) {
            // fraction: numerator above, denominator below
            int top_end = rr-1;
            int bot_start = rr+1;
            long long num = eval(r1, c1, top_end, c2);
            long long den = eval(bot_start, c1, r2, c2);
            if (den == 0) return 0;
            return num / den % MOD;
        }
    }

    // exponent: look for vertical bar
    for (int rr = r1; rr <= r2; rr++) {
        for (int cc = c1; cc <= c2; cc++) {
            if (expr[rr][cc] == '|') {
                // base is below, exponent above
                int base_top = rr+1;
                int exp_bot = rr-1;
                long long base = eval(base_top, c1, r2, c2);
                long long exp = eval(r1, c1, exp_bot, c2);
                long long res = 1;
                for (long long i = 0; i < exp; i++) {
                    res = (res * base) % MOD;
                }
                return res;
            }
        }
    }

    return 0;
}

long long eval(int r1, int c1, int r2, int c2) {
    if (r1 == r2) {
        return evalline(r1, c1, c2);
    }
    // Multi-line: fraction or exponent
    // Look for horizontal line of dashes
    for (int rr = r1; rr <= r2; rr++) {
        int hasdash = 0;
        for (int cc = c1; cc <= c2; cc++) {
            if (expr[rr][cc] == '-') hasdash = 1;
        }
        if (hasdash) {
            int top_end = rr-1;
            int bot_start = rr+1;
            long long num = eval(r1, c1, top_end, c2);
            long long den = eval(bot_start, c1, r2, c2);
            if (den == 0) return 0;
            return num / den % MOD;
        }
    }
    // vertical bar for exponent
    for (int rr = r1; rr <= r2; rr++) {
        for (int cc = c1; cc <= c2; cc++) {
            if (expr[rr][cc] == '|') {
                int base_top = rr+1;
                int exp_bot = rr-1;
                long long base = eval(base_top, c1, r2, c2);
                long long exp = eval(r1, c1, exp_bot, c2);
                long long res = 1;
                for (long long i = 0; i < exp; i++) {
                    res = (res * base) % MOD;
                }
                return res;
            }
        }
    }
    return 0;
}

int main() {
    while (1) {
        h = 0;
        while (1) {
