static int mod_norm(long long x) {
    x %= MOD;
    if (x < 0) x += MOD;
    return (int)x;
}

static int mod_pow(int a, int e) {
    long long r = 1, x = mod_norm(a);
    while (e > 0) {
        if (e & 1) r = (r * x) % MOD;
        x = (x * x) % MOD;
        e >>= 1;
    }
    return (int)r;
}

static int mod_inv(int a) {
    return mod_pow(a, MOD - 2);
}

typedef struct {
    int r1, r2, c1, c2; /* inclusive */
    int base;           /* baseline row */
} Expr;

/* trim empty outer rows/cols consisting only of spaces */
static Expr normalize(Expr e) {
    int changed = 1;
    while (changed) {
        changed = 0;
        int i, j, ok;
        while (e.r1 <= e.r2) {
            ok = 1;
            for (j = e.c1; j <= e.c2; ++j) if (g[e.r1][j] != ' ') { ok = 0; break; }
            if (!ok) break;
            e.r1++;
            changed = 1;
        }
        while (e.r1 <= e.r2) {
            ok = 1;
            for (j = e.c1; j <= e.c2; ++j) if (g[e.r2][j] != ' ') { ok = 0; break; }
            if (!ok) break;
            e.r2--;
            changed = 1;
        }
        while (e.c1 <= e.c2) {
            ok = 1;
            for (i = e.r1; i <= e.r2; ++i) if (g[i][e.c1] != ' ') { ok = 0; break; }
            if (!ok) break;
            e.c1++;
            changed = 1;
        }
        while (e.c1 <= e.c2) {
            ok = 1;
            for (i = e.r1; i <= e.r2; ++i) if (g[i][e.c2] != ' ') { ok = 0; break; }
            if (!ok) break;
            e.c2--;
            changed = 1;
        }
    }
    if (e.base < e.r1) e.base = e.r1;
    if (e.base > e.r2) e.base = e.r2;
    return e;
}

static int is_all_char_row(Expr e, int row, char ch) {
    if (row < e.r1 || row > e.r2) return 0;
    int j, seen = 0;
    for (j = e.c1; j <= e.c2; ++j) {
        if (g[row][j] == ch) seen = 1;
        else if (g[row][j] != ' ') return 0;
    }
    return seen;
}

static int eval_expr(Expr e);

static int eval_number(Expr e) {
    long long v = 0;
    int j;
    for (j = e.c1; j <= e.c2; ++j) {
        if (isdigit((unsigned char)g[e.base][j])) {
            v = (v * 10 + (g[e.base][j] - '0')) % MOD;
        }
    }
    return (int)v;
}

static int is_digit_block(Expr e) {
    int i, j, seen = 0;
    for (i = e.r1; i <= e.r2; ++i) {
        for (j = e.c1; j <= e.c2; ++j) {
            char ch = g[i][j];
            if (ch == ' ') continue;
            if (i != e.base || !isdigit((unsigned char)ch)) return 0;
            seen = 1;
        }
    }
    return seen;
}

static int find_main_pm(Expr e, int *pos) {
    int j;
    for (j = e.c1; j <= e.c2; ++j) {
        char ch = g[e.base][j];
        if (ch == '+' || ch == '-') {
            int i, ok = 1;
            for (i = e.r1; i <= e.r2; ++i) {
                if (i == e.base) continue;
                if (g[i][j] != ' ') { ok = 0; break; }
            }
            if (ok) {
                *pos = j;
                return 1;
            }
        }
    }
    return 0;
}

static int find_main_mul(Expr e, int *pos) {
    int j;
    for (j = e.c1; j <= e.c2; ++j) {
        char ch = g[e.base][j];
        if (ch == '*') {
            int i, ok = 1;
            for (i = e.r1; i <= e.r2; ++i) {
                if (i == e.base) continue;
                if (g[i][j] != ' ') { ok = 0; break; }
            }
            if (ok) {
                *pos = j;
                return 1;
            }
        }
    }
    return 0;
}

static int eval_expr(Expr e) {
    e = normalize(e);
    if (e.r1 > e.r2 || e.c1 > e.c2) return 0;

    int r;
    for (r = e.r1; r <= e.r2; ++r) {
        if (is_all_char_row(e, r, '-')) {
            Expr up = {e.r1, r - 1, e.c1, e.c2, r - 1};
            Expr dn = {r + 1, e.r2, e.c1, e.c2, r + 1};
            up = normalize(up);
            dn = normalize(dn);
            int a = eval_expr(up);
            int b = eval_expr(dn);
            return (int)((long long)a * mod_inv(b) % MOD);
        }
    }

    int p;
    if (find_main_pm(e, &p)) {
        Expr L = {e.r1, e.r2, e.c1, p - 1, e.base};
        Expr R = {e.r1, e.r2, p + 1, e.c2, e.base};
        int a = eval_expr(L);
        int b = eval_expr(R);
        if (g[e.base][p] == '+') return mod_norm(a + b);
        else return mod_norm(a - b);
    }

    if (find_main_mul(e, &p)) {
        Expr L = {e.r1, e.r2, e.c1, p - 1, e.base};
        Expr R = {e.r1, e.r2, p + 1, e.c2, e.base};
        int a = eval_expr(L);
        int b = eval_expr(R);
        return (int)((long long)a * b % MOD);
    }

    if (is_digit_block(e)) return eval_number(e);

    /* exponent: baseline part with upper-right exponent */
    int split = -1, j, i;
    for (j = e.c1; j <= e.c2; ++j) {
        int has_base = 0, has_upper = 0, has_lower = 0;
        for (i = e.c1; i <= j; ++i) {
            if (g[e.base][i] != ' ') { has_base = 1; break; }
        }
        for (i = e.r1; i < e.base; ++i) {
            int k;
            for (k = j + 1; k <= e.c2; ++k) {
                if (g[i][k] != ' ') { has_upper = 1; break; }
            }
            if (has_upper) break;
        }
        for (i = e.base; i <= e.r2; ++i) {
            int k;
            for (k = j + 1; k <= e.c2; ++k) {
                if (g[i][k] != ' ') { has_lower = 1; break; }
            }
            if (has_lower) break;
        }
        if (has_base && has_upper && !has_lower) split = j;
    }
    if (split != -1) {
        Expr A = {e.r1, e.r2, e.c1, split, e.base};
        Expr B = {e.r1, e.base - 1, split + 1, e.c2, e.base - 1};
        int a = eval_expr(A);
        int b = eval_expr(B);
        return mod_pow(a, b);
    }

    /* fallback: if single non-space char digit on baseline */
    return eval_number(e);
}

