            i += 1
        elif expr[i] == '^':
            tokens.append(('OP', '^'))
            i += 1
        else:
            i += 1
    return tokens

def apply_op(op, a, b):
    if op == '+':
        return (a + b) % MOD
    elif op == '-':
        return (a - b) % MOD
    elif op == '*':
        return (a * b) % MOD
    elif op == '^':
        return pow(a, b, MOD)

def precedence(op):
    if op == '+' or op == '-':
        return 1
    if op == '*' or op == '/':
        return 2
    if op == '^':
        return 3
    return 0

def evaluate(tokens):
