import sys

MOD = 2011

def modinv(a):
    a %= MOD
    return pow(a, MOD - 2, MOD)

class Parser:
    def __init__(self, grid, h, w):
        self.g = grid
        self.h = h
        self.w = w

    def row_nonspace_bounds(self, r, l, rr):
        mn = rr
        mx = l - 1
        row = self.g[r]
        for c in range(l, rr + 1):
            if row[c] != ' ':
                if mn == rr:
                    mn = c
                mx = c
        return mn, mx

    def col_nonspace_bounds(self, c, top, bot):
        mn = bot
        mx = top - 1
        for r in range(top, bot + 1):
            if self.g[r][c] != ' ':
                if mn == bot:
                    mn = r
                mx = r
        return mn, mx

    def trim(self, top, bot, l, r):
        while top <= bot:
            ok = False
            for c in range(l, r + 1):
                if self.g[top][c] != ' ':
                    ok = True
                    break
            if ok:
                break
            top += 1
        while top <= bot:
            ok = False
            for c in range(l, r + 1):
                if self.g[bot][c] != ' ':
                    ok = True
                    break
            if ok:
                break
            bot -= 1
        while l <= r:
            ok = False
            for rr in range(top, bot + 1):
                if self.g[rr][l] != ' ':
                    ok = True
                    break
            if ok:
                break
            l += 1
        while l <= r:
            ok = False
            for rr in range(top, bot + 1):
                if self.g[rr][r] != ' ':
                    ok = True
                    break
            if ok:
                break
            r -= 1
        return top, bot, l, r

    def is_all_char_row(self, row, l, r, ch='-'):
        seen = False
        for c in range(l, r + 1):
            if self.g[row][c] != ' ':
                seen = True
                if self.g[row][c] != ch:
                    return False
        return seen

    def parse_number(self, top, bot, l, r):
        if top != bot:
            return None
        s = ''.join(self.g[top][c] for c in range(l, r + 1)).strip()
        if not s or any(not ch.isdigit() for ch in s):
            return None
        return int(s) % MOD

    def baseline(self, top, bot, l, r):
        best = top
        bestcnt = -1
        for i in range(top, bot + 1):
            cnt = 0
            for c in range(l, r + 1):
                ch = self.g[i][c]
                if ch != ' ' and ch != '-':
                    cnt += 1
            if cnt > bestcnt:
                bestcnt = cnt
                best = i
        return best

    def split_top_level(self, top, bot, l, r, ops):
        base = self.baseline(top, bot, l, r)
        parts = []
        last = l
        i = l
        while i <= r:
            ch = self.g[base][i]
            if ch in ops:
                empty = True
                for rr in range(top, bot + 1):
                    if self.g[rr][i] != ' ':
                        if rr != base or self.g[rr][i] != ch:
                            empty = False
                            break
                if empty:
                    parts.append((last, i - 1, ch))
                    last = i + 1
            i += 1
        if not parts:
            return None
        segs = []
        cur_l = l
        opss = []
        for end, start_minus, op in parts:
            segs.append((cur_l, end))
            opss.append(op)
            cur_l = start_minus + 2
        segs.append((cur_l, r))
        return base, segs, opss

    def parse(self, top, bot, l, r):
        top, bot, l, r = self.trim(top, bot, l, r)
        if top > bot or l > r:
            return 0

        num = self.parse_number(top, bot, l, r)
        if num is not None:
            return num

        # Fraction: a row of '-' spanning all non-space content
        for mid in range(top + 1, bot):
            if self.is_all_char_row(mid, l, r, '-'):
                up_non = False
                dn_non = False
                for rr in range(top, mid):
                    for c in range(l, r + 1):
                        if self.g[rr][c] != ' ':
                            up_non = True
                            break
                    if up_non:
                        break
                for rr in range(mid + 1, bot + 1):
                    for c in range(l, r + 1):
                        if self.g[rr][c] != ' ':
                            dn_non = True
                            break
                    if dn_non:
                        break
                if up_non and dn_non:
                    a = self.parse(top, mid - 1, l, r)
                    b = self.parse(mid + 1, bot, l, r)
                    return a * modinv(b) % MOD

        # + and - at top level
        sp = self.split_top_level(top, bot, l, r, set('+-'))
        if sp is not None:
            base, segs, opss = sp
            vals = []
            for sl, sr in segs:
                vals.append(self.parse(top, bot, sl, sr))
            res = vals[0]
            for i, op in enumerate(opss):
                if op == '+':
                    res += vals[i + 1]
                else:
                    res -= vals[i + 1]
            return res % MOD

        # * at top level
        sp = self.split_top_level(top, bot, l, r, set('*'))
        if sp is not None:
            base, segs, opss = sp
            res = 1
            for sl, sr in segs:
                res = (res * self.parse(top, bot, sl, sr)) % MOD
            return res

        # Exponent: right-top attachment
        base = self.baseline(top, bot, l, r)

        # Find main body bounds around baseline
        body_l = r + 1
        body_r = l - 1
        for c in range(l, r + 1):
            if self.g[base][c] != ' ':
                body_l = min(body_l, c)
                body_r = max(body_r, c)

        if body_l <= body_r:
            # Check for superscript region strictly above baseline and to the right of body
            sup_exists = False
            sup_l = r + 1
            sup_r = l - 1
            sup_top = bot
            sup_bot = top - 1
            for rr in range(top, base):
                for c in range(body_r + 1, r + 1):
                    if self.g[rr][c] != ' ':
                        sup_exists = True
                        sup_l = min(sup_l, c)
                        sup_r = max(sup_r, c)
                        sup_top = min(sup_top, rr)
                        sup_bot = max(sup_bot, rr)
            if sup_exists:
                left_val = self.parse(top, bot, l, body_r)
                exp_val = self.parse(sup_top, sup_bot, sup_l, sup_r)
                return pow(left_val, exp_val, MOD)

        # If nothing else matched, parse as a single trimmed component
        # by connected bounding on all non-space chars
        return self.parse_number(top, bot, l, r) or 0


